-- ==============================================================================
-- Migration 002: Seed 36 Canonical Experience Cards with pgvector Embeddings
-- Idempotent, safe, and fixes match_experiences RPC column type definition.
-- ==============================================================================

-- 1. Ensure pgvector extension is enabled
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

-- 2. Ensure embedding column exists with 384 dimensions
ALTER TABLE public.experience_cards ADD COLUMN IF NOT EXISTS embedding extensions.vector(384);

-- 3. Make source_post_id nullable for canonical/seed experience cards
ALTER TABLE public.experience_cards ALTER COLUMN source_post_id DROP NOT NULL;

-- 4. Drop existing function (PostgreSQL requires DROP before changing RETURNS TABLE signature)
DROP FUNCTION IF EXISTS public.match_experiences CASCADE;

-- 5. Correct the match_experiences RPC definition (what_helped TEXT instead of TEXT[])
CREATE OR REPLACE FUNCTION public.match_experiences(
    query_embedding extensions.vector(384),
    match_threshold double precision DEFAULT 0.28,
    match_count INT DEFAULT 5
)
RETURNS TABLE (
    id UUID,
    created_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ,
    category TEXT,
    tags TEXT[],
    situation TEXT,
    what_helped TEXT,
    similarity double precision
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
    RETURN QUERY
    SELECT
        ec.id,
        ec.created_at,
        ec.updated_at,
        ec.category,
        ec.tags,
        ec.situation,
        ec.what_helped,
        (1 - (ec.embedding <=> query_embedding))::double precision AS similarity
    FROM public.experience_cards ec
    WHERE ec.embedding IS NOT NULL
      AND (1 - (ec.embedding <=> query_embedding)) >= match_threshold
    ORDER BY ec.embedding <=> query_embedding ASC
    LIMIT match_count;
END;
$$;

-- 6. Set Permissions and Row Level Security
ALTER TABLE public.experience_cards ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read of experience cards" ON public.experience_cards;
CREATE POLICY "Allow public read of experience cards" ON public.experience_cards FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow authenticated insert of experience cards" ON public.experience_cards;
CREATE POLICY "Allow authenticated insert of experience cards" ON public.experience_cards FOR INSERT TO authenticated WITH CHECK (true);

DROP POLICY IF EXISTS "Allow authenticated update of experience cards" ON public.experience_cards;
CREATE POLICY "Allow authenticated update of experience cards" ON public.experience_cards FOR UPDATE TO authenticated USING (true);

DROP POLICY IF EXISTS "Allow all for experience cards" ON public.experience_cards;
CREATE POLICY "Allow all for experience cards" ON public.experience_cards FOR ALL USING (true) WITH CHECK (true);

GRANT ALL ON public.experience_cards TO anon, authenticated, service_role, postgres;
GRANT EXECUTE ON FUNCTION public.match_experiences(extensions.vector(384), double precision, INT) TO anon, authenticated, service_role;

